// Función principal para aplicar el idioma
function cambiarIdioma(idioma) {
    localStorage.setItem('cs_idioma', idioma);

    const authContainer = document.getElementById('auth-container');
    if (authContainer) {
        const isLogged = localStorage.getItem('cs_username');
        if (isLogged) {
            authContainer.innerHTML = `
                <li><a href="usuario.html" data-i18n="menu_perfil">MI PERFIL</a></li>
                <li><a href="#" onclick="cerrarSesion(event)" data-i18n="menu_cerrar">CERRAR SESIÓN</a></li>
            `;
        } else {
            authContainer.innerHTML = `
                <li><a href="formulario registro.html" data-i18n="menu_registro">REGISTRO</a></li>
                <li><a href="login.html" data-i18n="menu_login">INICIAR SESIÓN</a></li>
            `;
        }
    }

    const elementos = document.querySelectorAll('[data-i18n]');
    if (traducciones[idioma]) {
        elementos.forEach(el => {
            const clave = el.getAttribute('data-i18n');
            if (traducciones[idioma][clave]) {
                if (el.tagName === 'INPUT') {
                    if (el.type === 'submit' || el.type === 'reset' || el.type === 'button') {
                        el.value = traducciones[idioma][clave];
                    } else if (el.hasAttribute('placeholder')) {
                        el.setAttribute('placeholder', traducciones[idioma][clave]);
                    }
                } else {
                    el.textContent = traducciones[idioma][clave];
                }
            }
        });
    }

    const selector = document.getElementById('selector-idioma');
    if (selector) {
        selector.value = idioma;
    }

    if (typeof ajustarMenuVisualmente === 'function') {
        ajustarMenuVisualmente();
    }
}

function cerrarSesion(event) {
    if(event) event.preventDefault();
    localStorage.removeItem('cs_username');
    localStorage.removeItem('cs_userphoto');
    window.location.reload();
}

// Función optimizada: desplaza el menú hacia la derecha y otorga mayor espaciado
function ajustarMenuVisualmente() {
    const enlaces = document.querySelectorAll('header nav ul li a');
    const ul = document.querySelector('header nav ul');
    const navContainer = document.querySelector('.nav-container');
    const logoBox = document.querySelector('.logo-box');

    if (!ul || !navContainer || !logoBox) return;

    enlaces.forEach(enlace => {
        enlace.style.whiteSpace = 'nowrap';
    });

    navContainer.style.display = 'flex';
    navContainer.style.justifyContent = 'space-between';
    navContainer.style.alignItems = 'center';

    ul.style.display = 'flex';
    ul.style.flexWrap = 'nowrap';
    ul.style.alignItems = 'center';

    // Espacio amplio entre opciones y separación del logotipo hacia la derecha
    ul.style.fontSize = '12px'; 
    ul.style.gap = '25px';      
    ul.style.marginLeft = '40px'; 
}

document.addEventListener("DOMContentLoaded", function() {
    const idiomaGuardado = localStorage.getItem('cs_idioma') || 'es';
    cambiarIdioma(idiomaGuardado);
});